import json, hashlib, difflib

v = json.load(open('/tmp/vul_funcs.json'))
x = json.load(open('/tmp/fix_funcs.json'))
def h(t): return hashlib.sha1(t.encode()).hexdigest()[:12]

vh, xh = {}, {}
for a,(s,t) in v.items(): vh.setdefault(h(t),[]).append(a)
for a,(s,t) in x.items(): xh.setdefault(h(t),[]).append(a)

only_v = sorted([a for hh,aa in vh.items() if hh not in xh for a in aa], key=lambda a:int(a,16))
only_x = sorted([a for hh,aa in xh.items() if hh not in vh for a in aa], key=lambda a:int(a,16))
print("unique-to-vul:", len(only_v), " unique-to-fix:", len(only_x))

# size-bucketed matching
xbysize = {}
for a in only_x: xbysize.setdefault(x[a][0],[]).append(a)

pairs=[]
used=set()
for a in only_v:
    t=v[a][1]; sz=v[a][0]
    cands=[]
    for ds in range(-16,17,8):
        for b in xbysize.get(sz+ds,[]):
            if b not in used: cands.append(b)
    best=None;bs=0
    for b in cands:
        sc=difflib.SequenceMatcher(None,t,x[b][1]).ratio()
        if sc>bs: bs=sc;best=b
    pairs.append((a,best,bs,sz,x[best][0] if best else -1))
    if best and bs>0.95: used.add(best)

print("HIGH similarity pairs (likely same func, patched):")
for a,b,sc,sz,szx in sorted(pairs,key=lambda p:-p[2]):
    if sc>0.90:
        print(f"  vul {a} (sz {sz})  fix {b} (sz {szx})  sim {sc:.3f}")
print("unmatched/low-sim vul funcs:")
for a,b,sc,sz,szx in sorted(pairs,key=lambda p:p[2]):
    if sc<=0.90:
        print(f"  vul {a} (sz {sz})  best fix {b} (sz {szx})  sim {sc:.3f}")
EOF
