# Check edges from 0x41e600 and down.
python3 -c "
import subprocess,re,json,bisect
from collections import deque
bin='/out-vul/hb-shape-fuzzer'
fl=json.loads(subprocess.run(['r2','-q','-e','bin.cache=true','-c','aaa; aflj',bin],capture_output=True,text=True,timeout=900).stdout)
funcs=sorted([(f['addr'],f['size']) for f in fl]); starts=[a for a,s in funcs]
def ff(a):
    i=bisect.bisect_right(starts,a)-1
    return funcs[i][0] if i>=0 and funcs[i][0]<=a<funcs[i][0]+max(funcs[i][1],1) else None
dis=subprocess.run(['objdump','-d','--no-show-raw-insn',bin],capture_output=True,text=True,timeout=300).stdout
edges={}
for m in re.finditer(r'^\s*([0-9a-f]+):\s+call\s+([0-9a-f]+)',dis,re.M):
    s=ff(int(m.group(1),16)); d=int(m.group(2),16)
    if s: edges.setdefault(s,set()).add(d)
# BFS from 0x415c30
for root in [0x415c30,0x415a20]:
    seen={root}; q=deque([root])
    while q:
        u=q.popleft()
        for v in edges.get(u,()):
            if v not in seen: seen.add(v); q.append(v)
    print(hex(root),'reaches 0x46adb0 get_glyph:', 0x46adb0 in seen)
    print('   cff funcs reached:', [hex(x) for x in sorted(seen) if 0x460000<=x<=0x4a0000])
"", "timeout": 290}

